import type { PodcastQuiz } from "@/data/podcast-quizzes";

const lit = (s: string) => `'${s.replace(/'/g, "''")}'`;

/**
 * The seed migration's full text, built from the authored data. scripts/gen-podcast-quiz-migration.ts writes it and
 * podcast-quiz-migration.test.ts fails when the committed file differs, so the data file stays the single source.
 * `evidence` (the transcript excerpt) is deliberately not part of it.
 */
export function buildPodcastQuizSeedSql(quizzes: PodcastQuiz[]): string {
  const out: string[] = [
    "-- GENERATED by scripts/gen-podcast-quiz-migration.ts from src/data/podcast-quizzes.ts. Do not edit by hand.",
    "-- Seeds the authored quiz questions. Episodes are matched by (course, folder slug, episode slug) because episode",
    "-- ids differ per database; an episode that does not exist in this database simply gets no questions.",
    "-- Re-running replaces the same questions (idempotent).",
    "",
  ];
  for (const quiz of quizzes) {
    out.push(`-- ${quiz.course}/${quiz.folder}/${quiz.slug}`);
    quiz.questions.forEach((question, i) => {
      out.push(
        `INSERT INTO public.podcast_quiz_questions (episode_id, id, prompt, choices, answer_index, sort_order)`,
        `SELECT e.id, ${lit(question.id)}, ${lit(question.prompt)}, ${lit(JSON.stringify(question.choices))}::jsonb, ${question.answerIndex}, ${i + 1}`,
        `FROM public.podcast_episodes e JOIN public.podcast_folders f ON f.id = e.folder_id`,
        `WHERE e.course = ${lit(quiz.course)} AND f.slug = ${lit(quiz.folder)} AND e.slug = ${lit(quiz.slug)}`,
        `ON CONFLICT (episode_id, id) DO UPDATE SET prompt = EXCLUDED.prompt, choices = EXCLUDED.choices,`,
        `  answer_index = EXCLUDED.answer_index, sort_order = EXCLUDED.sort_order;`,
      );
    });
    out.push("");
  }
  return out.join("\n");
}
